#!/usr/bin/env bash
# Publish the web app (web/ plus its generated data) to the gh-pages branch, which
# GitHub Pages serves at https://<owner>.github.io/<repo>/.
#
# web/data/ is generated by `subway export` and gitignored on main, so the site is
# built from the working tree into a fresh one-commit branch and force-pushed: the
# gh-pages branch never accumulates history (or multi-megabyte data diffs).
set -euo pipefail

root="$(git rev-parse --show-toplevel)"
cd "$root"

for f in web/data/day.json web/data/writeup.json; do
  [[ -f $f ]] || { echo "missing $f: run 'subway export' first" >&2; exit 1; }
done
if [[ -n "$(git status --porcelain -- web src)" ]]; then
  echo "warning: uncommitted changes in web/ or src/ will be published" >&2
fi

remote="$(git remote get-url origin)"
rev="$(git rev-parse --short HEAD)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

cp web/index.html web/app.js web/about.html web/about.js "$tmp/"
mkdir "$tmp/data"
cp web/data/day.json web/data/writeup.json "$tmp/data/"
touch "$tmp/.nojekyll"   # serve files as-is; no Jekyll processing

git -C "$tmp" init -q -b gh-pages
git -C "$tmp" add -A
git -C "$tmp" commit -q -m "Site build from $rev"
git -C "$tmp" push -q -f "$remote" gh-pages
echo "published $rev to gh-pages"
